/* @lc app=leetcode id=3472 lang=kotlin */ class Solution { fun longestPalindromicSubsequence(s: String, k: Int): Int = s.length.let { n -> Array(n + 2) { Array(n + 2) { IntArray(k + 1) } }.also { f -> (0 until n).forEach { i -> (0..k).forEach { c -> f[i][i][c] = 1 } } }.also { f -> (2..n).forEach { len -> (0..n - len).forEach { i -> (i + len - 1).let { j -> Math.abs(s[i] - s[j]).let { df -> minOf(df, 26 - df).let { cost -> (0..k).forEach { c -> f[i][j][c] = maxOf(f[i + 1][j][c], f[i][j - 1][c], if (cost <= c) f[i + 1][j - 1][c - cost] + 2 else 0) } } } } } } }.let { it[0][n - 1][k] } } }